import{_ as t,d as a,e as o,x as r}from"./chunks/framework.BRr8VP3a.js";const d=JSON.parse('{"title":"问题已经冻结，还能重新提问吗","description":"旧结果保留，新问题有理由地另立；冻结不取消受影响者对定题的质疑。","frontmatter":{"title":"问题已经冻结，还能重新提问吗","description":"旧结果保留，新问题有理由地另立；冻结不取消受影响者对定题的质疑。"},"headers":[],"relativePath":"concepts/reopening-questions.md","filePath":"concepts/reopening-questions.md"}'),n={name:"concepts/reopening-questions.md"};function p(s,e,i,c,_,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="问题已经冻结-还能重新提问吗" tabindex="-1">问题已经冻结，还能重新提问吗 <a class="header-anchor" href="#问题已经冻结-还能重新提问吗" aria-label="Permalink to &quot;问题已经冻结，还能重新提问吗&quot;">​</a></h1><p>旧结果保留，新问题有理由地另立；冻结不取消受影响者对定题的质疑。</p><p>预先说好怎样算成功，才能诚实评价结果。问题是：原先没被算进来的人，是否从此不能质疑目标、成员边界或损失定义？</p><p>v2的<a href="./../theory/part-02.html#section-2-14">§2.14</a>同时保留冻结与重开。重开可以因为现有表示不足以回答原问，也可以因为原问题本身遗漏利益、成员、损失或把可改变的约束当成给定。</p><p>教学情景：一项排班只以服务数量为目标，数量达标后，有人指出连续待命切断了照护与休息时间。原服务数量结果仍然成立；新的负担问题需要另立并核对材料。不能为维护旧目标而抹去负担，也不能因此把已达标的数量改写成没有发生。</p><p>重开应保留提出者、理由、处理依据和旧结果，说明新旧问题是替代、并列还是细化。即使请求被拒绝，也要留下理由和可质疑的入口。分析者可以并列回答；制度内的实际目标、资格和资源调整仍由有权限的程序决定。</p><p>如果只是因为失败而把截止日期延后，就不能称旧计划成功。结果可以暴露真正的遗漏，却不能自动成为任意换题的许可证。新任务成功与旧任务完成是两项结论。</p><p>继续阅读：<a href="./../theory/part-02.html#section-2-12">§2.12前瞻边界</a>、<a href="./../theory/part-04.html#section-4-19">§4.19任务族</a>、<a href="./history.html">学习与历史</a>。</p>',8)])])}const m=t(n,[["render",p]]);export{d as __pageData,m as default};
